import{_ as a,o as r,c as s,a2 as t}from"./chunks/framework.DaGSOal_.js";const m=JSON.parse('{"title":"K","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/k.md","filePath":"glossaire-a-z/k.md"}'),n={name:"glossaire-a-z/k.md"};function i(o,e,l,u,c,d){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="k" tabindex="-1">K <a class="header-anchor" href="#k" aria-label="Permalink to &quot;K&quot;">​</a></h1><h2 id="k-parameter-k-factor-fr-parametre-k" tabindex="-1">K Parameter (K Factor) (fr : Paramètre K) <a class="header-anchor" href="#k-parameter-k-factor-fr-parametre-k" aria-label="Permalink to &quot;K Parameter (K Factor) (fr : Paramètre K)&quot;">​</a></h2><p>Un paramètre du protocole Cardano qui définit le nombre cible de pools de staking que le réseau vise à soutenir pour favoriser une décentralisation optimale. Il influence la distribution des récompenses en rendant les pools excessivement grands moins attractifs, ce qui encourage la délégation vers un plus grand nombre de pools.</p><h2 id="key-evolving-signatures-kes-fr-signatures-a-cles-evolutives" tabindex="-1">Key Evolving Signatures (KES) (fr : Signatures à clés évolutives) <a class="header-anchor" href="#key-evolving-signatures-kes-fr-signatures-a-cles-evolutives" aria-label="Permalink to &quot;Key Evolving Signatures (KES) (fr : Signatures à clés évolutives)&quot;">​</a></h2><p>Les KES sont des clés cryptographiques utilisées par les opérateurs de pools de staking Cardano pour signer les blocs. Contrairement aux clés statiques, elles sont conçues pour évoluer au fil du temps, réduisant ainsi le risque lié à la compromission prolongée d’une clé, tout en contribuant à une production de blocs sécurisée et continue.</p><h2 id="key-management-fr-gestion-des-cles" tabindex="-1">Key Management (fr : Gestion des clés) <a class="header-anchor" href="#key-management-fr-gestion-des-cles" aria-label="Permalink to &quot;Key Management (fr : Gestion des clés)&quot;">​</a></h2><p>Désigne les processus et les outils utilisés pour générer, stocker, utiliser et protéger les clés cryptographiques qui contrôlent l’accès aux jetons et aux fonctions d’une blockchain.</p><h2 id="key-pair-fr-paire-de-cles" tabindex="-1">Key Pair (fr : Paire de clés) <a class="header-anchor" href="#key-pair-fr-paire-de-cles" aria-label="Permalink to &quot;Key Pair (fr : Paire de clés)&quot;">​</a></h2><p>Désigne une clé privée et la clé publique correspondante, générées à l’aide de la cryptographie. Dans une blockchain, la clé privée permet à un utilisateur d’autoriser des transactions, tandis que la clé publique — ou l’adresse qui en est dérivée — peut être partagée pour recevoir des jetons.</p><h2 id="know-your-customer-kyc-fr-connaissance-du-client" tabindex="-1">Know Your Customer (KYC) (fr : Connaissance du client) <a class="header-anchor" href="#know-your-customer-kyc-fr-connaissance-du-client" aria-label="Permalink to &quot;Know Your Customer (KYC) (fr : Connaissance du client)&quot;">​</a></h2><p>Désigne le processus réglementaire par lequel les institutions financières et les fournisseurs de services vérifient l’identité de leurs clients. Dans le contexte de la blockchain, le KYC est souvent exigé des plateformes d’échange, des dépositaires et d’autres intermédiaires réglementés afin de respecter les obligations de lutte contre le blanchiment d’argent (AML).</p>',11)])])}const f=a(n,[["render",i]]);export{m as __pageData,f as default};
